-- STATES
INSERT OR REPLACE INTO states (slug, name, tagline, craft_history, hero_image, accent_hex, display_order) VALUES ('gujarati', 'Gujarat Patan & Kutch', 'Imperial Double Ikat, Kutchi Bandhej & Royal Panetar Drapes', 'Celebrated for mathematical precision in Patan Patola double ikat where both warp and weft are resist-dyed before weaving. Complemented by intricate Kutchi tie-dye Bandhani, ceremonial maternal Panetar, auspicious 52-kundi Gharchola bridal silks, and embossed Sultanate court Ashavali brocades.', '/collections/gujarati/hero.jpg', '#D92D20', 1);
INSERT OR REPLACE INTO states (slug, name, tagline, craft_history, hero_image, accent_hex, display_order) VALUES ('rajasthani', 'Rajasthan · Jaipur, Kota & beyond', 'A visual study of Rajasthan’s living textile traditions', 'Rajasthan is associated with Leheriya and Bandhej resist dyeing, Kota Doria weaving, and Bagru and Sanganeri block printing. This DRIFT collection uses those traditions as design references; it does not claim the displayed concept listings are authentic examples of those crafts.', '/collections/rajasthani/hero.jpg', '#E65100', 2);
INSERT OR REPLACE INTO states (slug, name, tagline, craft_history, hero_image, accent_hex, display_order) VALUES ('jodhpuri', 'Jodhpur & Marwar', 'Bandhej, Leheriya and festive drapes from Rajasthan', 'Jodhpur is associated with Bandhej tie-dye. Rajasthan craft references also document Leheriya and Mothda resist-dye patterns. This DRIFT edit presents contemporary design concepts inspired by these techniques; maker and material details are pending verification.', '/collections/jodhpuri/hero.jpg', '#800020', 3);
INSERT OR REPLACE INTO states (slug, name, tagline, craft_history, hero_image, accent_hex, display_order) VALUES ('banarasi', 'Varanasi Banaras & Awadh', 'Banaras Brocades & Awadh Embroidery — Style Studies', 'Banaras brocades and sarees are a GI-registered handloom tradition known for silk, zari ornament, floral and foliate motifs, jali patterns, and meena work. Named Banaras varieties include Jangla, Tanchoi, Vaskat, Cutwork, Tissue, and Butidar. Lucknow chikankari is a distinct Awadh embroidery tradition. The pieces shown here are illustrative concepts; their materials, maker, origin, and authenticity are not verified.', '/collections/banarasi/hero.jpg', '#9A1B28', 4);
INSERT OR REPLACE INTO states (slug, name, tagline, craft_history, hero_image, accent_hex, display_order) VALUES ('kanchipuram', 'Tamil Nadu & South India', 'Kanchipuram, Mysore & Kerala textile traditions', 'This collection is an editorial study of South Indian textile traditions. Kancheepuram Silk is a registered Geographical Indication from Tamil Nadu. Mysore Silk is a separate Karnataka GI associated with KSIC production, while Kerala Kasavu is commonly seen in cream cotton with a zari border. These records are design concepts, not verified DRIFT stock.', '/collections/kanchipuram/hero.jpg', '#B7094C', 5);
INSERT OR REPLACE INTO states (slug, name, tagline, craft_history, hero_image, accent_hex, display_order) VALUES ('heritage-states', 'Maharashtra, Central & East India', 'Paithani, Chanderi, Sambalpuri Bandha & Assam Muga design studies', 'This DRIFT concept edit takes design references from Maharashtra’s Paithani and Narayan Peth, Madhya Pradesh’s Chanderi and Maheshwari, Odisha’s Sambalpuri Bandha and Bomkai, Assam’s Muga silk, and West Bengal’s Baluchari. Narayan Peth around Solapur is distinct from Telangana’s GI-registered Narayanpet saree. The collection is not sourced product inventory: makers, exact materials, production locations, and GI eligibility remain unverified.', '/collections/heritage-states/hero.jpg', '#105652', 6);

-- SAREES
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-01', 'DRIFT-RAJWADA-NAVRATNA-PATAN-P', 'Masterpiece Double Ikat Pure Silk Patan Patola · Concept Study', 'gujarati', 'Craft inspiration: Patan, Gujarat · production provenance to confirm', 'Patan Patola Double Ikat', 'Concept study — material to confirm with maker', 45000, 54000, 'Craft style study', '["#8E1818","#14213D","#D4AF37","#2A4736"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'Celebrated since the 11th-century Solanki dynasty under King Kumarapala, Patan Patola represents double-ikat mathematical weaving. Both warp and weft silk yarns are individually tied and dyed with natural resist dyes before weaving on slanted rosewood looms, producing mirrored motifs identical on both sides. This design study draws from the revered Navratna (Nine Gems) pattern. Specific maker, production, and SKU details require confirmation.', '/collections/gujarati/saree_01_primary.jpg', '/collections/gujarati/saree_01_detail.jpg', 1, 1, 'Seedha Pallu Royal Gujarati Pleat', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-02', 'DRIFT-KUTCHI-GAJJI-SILK-BANDHA', 'Heirloom Gajji Silk Sindoori Micro-Knot Bandhej · Concept Study', 'gujarati', 'Craft inspiration: Kutch and Mandvi, Gujarat · production provenance to confirm', 'Kutchi Hand-Tied Bandhej', 'Concept study — material to confirm with maker', 45000, 54000, 'Craft style study', '["#9E1B32","#D4AF37","#E85D04","#1A1A1A"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'Practiced by Khatri artisan communities across Bhuj, Anjar, and Mandvi in Kutch. Fine high-twist mulberry gajji silk is pinched and tied with resist thread into thousands of microscopic ''bindi'' knots before immersion into traditional madder crimson and saffron dyes. This design study explores the tactile crinkled texture and lagdi patta gold border. Specific maker, production, and SKU details require confirmation.', '/collections/gujarati/saree_02_primary.jpg', '/collections/gujarati/saree_02_detail.jpg', 0, 0, 'Gujarati Front-Facing Pallu Drape', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-03', 'DRIFT-ROYAL-GUJARATI-IVORY-PAN', 'Imperial Ivory Silk Bridal Panetar with Crimson Zari Border · Concept Study', 'gujarati', 'Craft inspiration: Gujarati Panetar tradition · production provenance to confirm', 'Traditional Panetar Weave', 'Concept study — material to confirm with maker', 45000, 54000, 'Craft style study', '["#F4EBD9","#8C1D2F","#D4AF37","#222222"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'The sacred bridal heirloom gifted by the maternal family (Mameru) for traditional Gujarati wedding rituals. Pure mulberry raw silk woven in ceremonial ivory or pearl white, contrasted by a wide vermilion madder border and heavily brocaded with Kalpavriksha (Tree of Life) motifs in rich gold zari symbolizing prosperity and maternal blessings. Specific maker, production, and SKU details require confirmation.', '/collections/gujarati/saree_03_primary.jpg', '/collections/gujarati/saree_03_detail.jpg', 1, 0, 'Traditional Gujarati Bridal Front Drape', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-04', 'DRIFT-BRIDAL-SHUBH-GHARCHOLA', 'Auspicious Gajji Silk Gharchola with 52 Kundis Zari Grid · Concept Study', 'gujarati', 'Craft inspiration: Jamnagar, Gujarat · production provenance to confirm', 'Gajji Silk 52-Kundi Gharchola', 'Concept study — material to confirm with maker', 45000, 54000, 'Craft style study', '["#800020","#D4AF37","#5C061A","#E9C46A"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'The ceremonial drape gifted by the groom''s mother (Sasu) welcoming the bride into the new household. Traditionally woven on pure gajji silk in Jamnagar, divided mathematically into an auspicious grid of 52 squares (Bavan Kundi) in pure gold zari, with hand-tied Bandhej peacocks, elephants, and kalash emblems in each box. Specific maker, production, and SKU details require confirmation.', '/collections/gujarati/saree_04_primary.jpg', '/collections/gujarati/saree_04_detail.jpg', 1, 0, 'Head Veil Over Shoulder Pleats', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-05', 'DRIFT-AMDAVAD-DARBAR-ASHAVALI-', 'Heritage Ashavali Brocade Gold Tissue Silk Saree · Concept Study', 'gujarati', 'Craft inspiration: Ahmedabad, Gujarat · production provenance to confirm', 'Ashavali Royal Brocade', 'Concept study — material to confirm with maker', 45000, 54000, 'Craft style study', '["#C5A059","#092E20","#631B29","#EFE9D9"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'Dating to the 16th-century Ahmedabad Sultanate court, Ashavali brocades are celebrated for three-dimensional embossed weaving (badla) where gold zari motifs rise like relief carvings. Featuring the iconic Mor-jaal (peacock trellis) with ruby and emerald meenakari silk insets. Specific maker, production, and SKU details require confirmation.', '/collections/gujarati/saree_05_primary.jpg', '/collections/gujarati/saree_05_detail.jpg', 0, 0, 'Cascading Pleats with Broad Pallu Display', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-06', 'DRIFT-PATAN-CHHABDI-BHAT-HEIRL', 'Patan Double Ikat Floral Basket Chhabdi Bhat · Concept Study', 'gujarati', 'Craft inspiration: Patan, Gujarat · production provenance to confirm', 'Patan Double Ikat Silk', 'Concept study — material to confirm with maker', 45000, 54000, 'Craft style study', '["#58111A","#133926","#D4AF37","#EFE4B0"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'A revered archival Patan Patola variation characterized by repeating ''Chhabdi'' (woven floral basket) geometric compartments. Each basket holds stylised lotuses, jasmine buds, and parakeets, representing one of the most mathematically rigorous double-ikat layouts in Indian textile history. Specific maker, production, and SKU details require confirmation.', '/collections/gujarati/saree_06_primary.jpg', '/collections/gujarati/saree_06_detail.jpg', 0, 0, 'Nivi Drape with Open Pallu', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-07', 'DRIFT-MANDVI-MOR-MAYUR-BANDHEJ', 'Deep Crimson Gajji Silk Peacock Bandhej Saree · Concept Study', 'gujarati', 'Craft inspiration: Kutch and Mandvi, Gujarat · production provenance to confirm', 'Mandvi Fine Knot Bandhej', 'Concept study — material to confirm with maker', 45000, 54000, 'Craft style study', '["#8B0000","#0B2D39","#D4AF37","#F5E6A3"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'Rooted in the coastal trade town of Mandvi, this style pairs diagonal wave resist-dyeing with intricate floral and dancing peacock panels. Woven on lustrous gajji silk with heavy zari pallu finishing, capturing traditional celebratory festive aesthetics. Specific maker, production, and SKU details require confirmation.', '/collections/gujarati/saree_07_primary.jpg', '/collections/gujarati/saree_07_detail.jpg', 1, 0, 'Shoulder Pleated Pallu', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-08', 'DRIFT-JAMNAGAR-TWILIGHT-GEORGE', 'Pure Silk Georgette Twilight Ombre Bandhani · Concept Study', 'gujarati', 'Craft inspiration: Jamnagar, Gujarat · production provenance to confirm', 'Jamnagar Precision Dip-Dye Bandhani', 'Concept study — material to confirm with maker', 45000, 54000, 'Craft style study', '["#42162E","#0D1B2A","#D4AF37","#9A824A"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'A contemporary interpretation of Jamnagar dip-dye artistry. Fine pure silk georgette dyed in a twilight ombre from deep royal plum to midnight indigo, punctuated by constellations of hand-tied micro dots (Rani Bindi) and a scalloped gold zari border. Specific maker, production, and SKU details require confirmation.', '/collections/gujarati/saree_08_primary.jpg', '/collections/gujarati/saree_08_detail.jpg', 0, 0, 'Fluid Modern Saree Drape', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-09', 'DRIFT-PATAN-MASHRU-SATIN-STUDY', 'Patan Mashru Satin-Faced Textile · Saree Design Study', 'gujarati', 'Patan Mashru reference · maker and production provenance to confirm', 'Patan Mashru Weaving', 'Concept study — fiber composition to confirm', 45000, 54000, 'Craft style study', '["#233757","#8D3046","#D6B66D","#E9DEC8"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'Mashru is a distinctive Gujarat textile tradition; government craft references describe its characteristic silk-faced, cotton-backed structure. This visual direction adapts that textile reference for a saree study and does not certify a specific fabric or garment.', '/collections/models/priya_gujarati_patola.jpg', '/collections/gujarati/saree_05_detail.jpg', 0, 1, 'Seedha Pallu', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-10', 'DRIFT-KUTCH-AJRAKH-INDIGO-STUD', 'Kutch Ajrakh-Printed Saree Styling Study', 'gujarati', 'Kutch Ajrakh reference · maker and production provenance to confirm', 'Kutch Ajrakh Block-Print Inspiration', 'Concept study — base cloth to confirm', 45000, 54000, 'Craft style study', '["#183750","#8E303A","#D8B56B","#EAE0C9"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'Ajrakh is a block-printing tradition practiced in Kutch. Here its repeat geometry and deep indigo palette are translated into a saree design study; printing method, dyes, cloth, and maker are not verified.', '/collections/models/priya_jodhpuri_bandhani.jpg', '/collections/gujarati/saree_02_detail.jpg', 0, 0, 'Gujarati Seedha Pallu', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-11', 'DRIFT-SURENDRANAGAR-TANGALIYA-', 'Tangaliya-Inspired Dotted Drape · Saree Design Study', 'gujarati', 'Surendranagar Tangaliya reference · maker and production provenance to confirm', 'Tangaliya Weaving Inspiration', 'Concept study — material and technique to confirm', 45000, 54000, 'Craft style study', '["#126B68","#E18A72","#D6B86F","#F2E7D2"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'Tangaliya is a distinctive dotted weaving tradition associated with Surendranagar and the Dangasia community. This DRIFT study borrows the visual rhythm as an experimental saree direction, rather than claiming a traditional Tangaliya saree.', '/collections/models/priya_kanchipuram_purple.jpg', '/collections/gujarati/saree_06_detail.jpg', 0, 0, 'Lightweight Gujarati Drape', 25);
INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('guj-12', 'DRIFT-SAURASHTRA-SINGLE-IKAT-S', 'Saurashtra Single-Ikat Color-Block · Saree Design Study', 'gujarati', 'Surendranagar single-ikat reference · maker and production provenance to confirm', 'Surendranagar Single Ikat Inspiration', 'Concept study — fiber and weave to confirm', 45000, 54000, 'Craft style study', '["#9D2D3A","#E2A13B","#176C69","#EEDDBA"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'Single ikat appears among Gujarat textile references documented for Surendranagar. This palette and layout reinterpret the broader resist-dyed geometry for an editorial saree concept; no specific technique is verified for a product.', '/collections/models/priya_gujarati_panetar.jpg', '/collections/gujarati/saree_07_detail.jpg', 0, 0, 'Seedha Pallu', 25);
