INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) VALUES ('her-10', 'DRIFT-HER-10-NARAYAN-PETH-BORD', 'DRIFT design concept — Narayan Peth Border & Butti Study', 'heritage-states', 'Cultural reference only; no maker, workshop, GI status or production origin verified for this concept.', 'Narayan Peth-inspired traditional border concept', 'Fibre content and sourcing to be confirmed', 45000, 54000, 'Illustrative design study', '["#273E73","#B13A55","#C4A05D","#F2E8D8"]', '["Unstitched","34 (XS)","36 (S)","38 (M)","40 (L)","42 (XL)"]', 'A Maharashtra textile design reference inspired by the contrast borders and butti vocabulary associated with Narayan Peth sarees around Solapur. This local design reference is distinct from Narayanpet Handloom Sarees, the separately registered Telangana GI. The image is a styling concept; weave, fibre and local provenance remain unverified.', '/collections/models/regional-model-10.jpg', '/collections/models/regional-model-10.jpg', 0, 0, 'Illustrative styling concept; drape construction not verified', 25);